package br.com.conectatea.meta.domain;
import br.com.conectatea.shared.domain.AuditableEntity; import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="metas") public class Meta extends AuditableEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String titulo; @Column(columnDefinition="text") private String descricao; @Enumerated(EnumType.STRING) private CategoriaMeta categoria; @Enumerated(EnumType.STRING) private PrioridadeMeta prioridade; @Enumerated(EnumType.STRING) private StatusMeta status; private int progresso; @Column(name="data_inicio") private LocalDate dataInicio; @Column(name="data_fim") private LocalDate dataFim; @Column(name="crianca_id") private Long criancaId; @Column(name="profissional_id") private Long profissionalId; @Version private long version; protected Meta(){} public Meta(String t,String d,CategoriaMeta c,PrioridadeMeta p,LocalDate i,LocalDate f,Long child,Long professional){titulo=t;descricao=d;categoria=c;prioridade=p;dataInicio=i;dataFim=f;criancaId=child;profissionalId=professional;status=StatusMeta.EM_ANDAMENTO;} public Long getId(){return id;} public String getTitulo(){return titulo;} public String getDescricao(){return descricao;} public CategoriaMeta getCategoria(){return categoria;} public PrioridadeMeta getPrioridade(){return prioridade;} public StatusMeta getStatus(){return statusAtual(LocalDate.now());} public int getProgresso(){return progresso;} public LocalDate getDataInicio(){return dataInicio;} public LocalDate getDataFim(){return dataFim;} public Long getCriancaId(){return criancaId;} public Long getProfissionalId(){return profissionalId;} public void update(String t,String d,CategoriaMeta c,PrioridadeMeta p,LocalDate i,LocalDate f){titulo=t;descricao=d;categoria=c;prioridade=p;dataInicio=i;dataFim=f;status=statusAtual(LocalDate.now());} public void progress(int value){progresso=value;status=statusAtual(LocalDate.now());} public StatusMeta statusAtual(LocalDate today){if(progresso==100)return StatusMeta.CONCLUIDA;if(progresso>=90)return StatusMeta.QUASE_CONCLUIDA;if(dataFim!=null&&!dataFim.isBefore(today)&&!dataFim.isAfter(today.plusDays(7)))return StatusMeta.VENCENDO;return StatusMeta.EM_ANDAMENTO;} }
